-- HONEST-MEASURE-HANDOFF-1 (2026-11-05, charter pillar autonomy; roadmap_implementation 3260 RM-BS-HONEST-MEASURE-1, blue-sky bet B4, program QNFO.OPS; session W2-H).
-- WHAT: row 3260 keeps status planned (no code of its own has shipped) and gets its evidence: the W0 first reading that exists, what was read in D1 and the code on 2026-11-05, and the
--   two slices filed as agent_issues with a code-task, a unique code-anchor, a code-probe, a definition of done and what not to touch, written so any code agent can pick them up cold.
--   (.1) metric_noise_floor: every outcome measure gets a published noise floor and minimum detectable effect (MEAS-01). (.2) the floor is used: improvementEvaluate shadows then applies a
--   "within noise" verdict, and the PLUSSING-4 keep-or-revert window is sized from it.
-- WHY these two first: the doc says every other bet is judged by B4, and the first reading (docs/BLUE-SKY-ROADMAP-2026-11.md, B4) shows a 7-day reader comparison cannot see a change smaller than
--   +7.4 a day (145 percent of the mean). v_output_quality_verdict judges "moved" with a fixed tol_rel (0.05 to 0.3) and no noise floor, so a flat or noisy measure can read better or worse by chance.
-- PREDICTION (decision_log): after .1 is merged and has run one improvement-loop tick, metric_noise_floor holds one row per outcome measure (14) plus the reader series, at least 5 with state ok;
--   the reader series reads mde_7d between 3 and 12 a day. Falsifier: fewer than 14 rows after two hourly ticks, or an ok row with a negative or NULL sd.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261105_honest_measure_roadmap
-- Rollback: UPDATE roadmap_implementation SET status = (SELECT b.status FROM bak_20261105_honest_measure_roadmap b WHERE b.id = roadmap_implementation.id), evidence = (SELECT b.evidence FROM bak_20261105_honest_measure_roadmap b WHERE b.id = roadmap_implementation.id) WHERE id = 3260; UPDATE agent_issues SET status = 'closed' WHERE source = 'session:W2-H-3260' AND title LIKE 'ROADMAP-1: QNFO.OPS RM-BS-HONEST-MEASURE-1.%' AND status = 'open';
-- CAUSE-MAPPED: registers no metric_registry row; the issues carry code-probe contracts and the metric is registered by .1 with its trigger.

CREATE TABLE IF NOT EXISTS bak_20261105_honest_measure_roadmap AS SELECT * FROM roadmap_implementation WHERE id = 3260;

UPDATE roadmap_implementation
SET evidence = COALESCE(evidence, '') || ' | ' || 'W2-H 2026-11-05 handoff (no code shipped for this row yet; status stays planned): the B4 W0 first reading is in the doc (reader_yield_daily.ga4_engaged_external, 11 days: mean 5.1, sd 5.0, smallest detectable effect of two 7-day windows +7.4 a day, 14-day +5.2, 28-day +3.7). Read in D1 on 2026-11-05: output_quality_measures holds 14 outcome rows and metric_history holds daily points for them in the last 28 days as follows: 29 points for q08_human_reads_7d, social_engagement_rate_30d, engaged_human_sessions_28d, code_task_success_rate_30d, remediation_latest_pass_pct_7d; 11 for papers_with_open_high_errata_pct, errata_high_net_inflow_7d, q08_retraction_rate_30d; 6 for engaged_reader_sessions_7d, research_neurons_per_engaged_session_7d, social_engaged_sessions_7d; 2 for ask_helpful_rate_30d; 0 for jobsearch_reply_rate_90d and youtube_avg_view_duration_s. v_output_quality_verdict judges moved with a fixed tol_rel and no noise floor. Slices filed with code-task, anchor, probe and definition of done: RM-BS-HONEST-MEASURE-1.1 (metric_noise_floor in qnfo-fleet-control) and RM-BS-HONEST-MEASURE-1.2 (the floor shadows then gates the improvement loop verdict and sizes the PLUSSING-4 window), doer qnfo-code-orchestrator. Still open on this row after those: seeded known errors and monthly reviewer recall (MEAS-03), first-party reader ledger (CF-B-05), invoice-grade cost (CF-A-16), answer-engine loop (CF-A-10), owner labels and prediction-powered intervals (MEAS-04), re-scored human anchors (MEAS-02), the 5 percent holdout (MEAS-07); each is filed by the doer of .2 as the next ROADMAP-1 row when .2 merges.'
WHERE id = 3260 AND COALESCE(evidence, '') NOT LIKE '%W2-H 2026-11-05 handoff%';

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'ROADMAP-1: QNFO.OPS RM-BS-HONEST-MEASURE-1.1: every outcome measure gets a published noise floor and minimum detectable effect (table metric_noise_floor, route /noise-floor)',
 'QNFO.OPS; charter pillar autonomy; roadmap row 3260 (RM-BS-HONEST-MEASURE-1), blue-sky bet B4 step MEAS-01 (docs/BLUE-SKY-ROADMAP-2026-11.md, section B4); doer: qnfo-code-orchestrator via the code-task line. Metric it should move: outcome measures with a published noise floor (target: all 14 rows of output_quality_measures with role outcome have a metric_noise_floor row, state ok or an honest insufficient_history; 6 have 11 or fewer daily points today). Prediction: within 30 days every metric in v_output_quality_headline has a floor and the verdict names which movements are below it.' || char(10) || char(10) ||
 'WHY (read 2026-11-05): metric_history(metric, day, value, meets, target, ts) with primary key (metric, day) is the daily series (qnfo-fleet-control keeps it in improvementLoopTick). output_quality_measures(metric, surface, role, polarity, tol_rel, tol_abs, judged_by, caveat) has 14 outcome rows. v_output_quality_verdict decides better, worse or flat with the fixed tol_rel of each row (0.05 to 0.3), so nothing says when a move is inside the noise. The first reading of the reader series (reader_yield_daily.ga4_engaged_external, 11 complete days, mean 5.1, sd 5.0, variance 4.8 times the mean) shows the smallest effect two 7-day windows can tell apart is +7.4 a day (145 percent of the mean), two 14-day windows +5.2, two 28-day windows +3.7.' || char(10) || char(10) ||
 'WORK: (1) New migration migrations/2026-11-06-honest-measure-noise-floor.sql (headers -- APPLY-BY: ci, -- DB: qnfo-audit, -- Rollback: DROP VIEW ...; DROP TABLE ...; plus -- CAUSE-MAPPED: line or a metric_breach_cause row if you register a metric; copy the header style of migrations/2026-11-01-plussing-4.sql) creating table metric_noise_floor(metric TEXT PRIMARY KEY, role TEXT, basis TEXT, native_window_d INTEGER, n_points INTEGER, mean REAL, sd REAL, dispersion REAL, mde_7d REAL, mde_14d REAL, mde_28d REAL, mde_7d_rel REAL, mde_28d_rel REAL, state TEXT, caveat TEXT, computed_at TEXT) and two views: v_output_quality_noise (every output_quality_measures outcome row LEFT JOIN metric_noise_floor, with a column tol_below_noise = 1 when the row tol_rel is smaller than mde_7d_rel) and v_metric_window_needed(metric, window_days, detectable_at_tol) giving the smallest of 7, 14 or 28 whose mde_rel is at most the tol_rel of the measure, else 28 with detectable_at_tol 0. (2) In qnfo-fleet-control/worker.js, inside the block between the markers IMPROVEMENT-LOOP-1:BEGIN and IMPROVEMENT-LOOP-1:END, add the pure function ilNoiseFloor(points, nativeWindowDays) right after ilMean, and a step in improvementLoopTick(env) that runs once per UTC day (skip when max(computed_at) of metric_noise_floor is today, and when ops_config noise_floor_tick is off). Read with indexed lookups only: SELECT metric, day, value FROM metric_history WHERE metric IN (the outcome metrics) AND day >= date(now, -60 days) (14 metrics, at most about 850 rows; never a table scan), plus SELECT day, ga4_engaged_external FROM reader_yield_daily ORDER BY day DESC LIMIT 60 stored under the metric key ga4_engaged_external_daily. Upsert one row per metric into metric_noise_floor. (3) Add GET /noise-floor next to the /improvement route (open read, OPEN-ACCESS-1) returning {ok, worker_version, computed_at, metrics:[...rows...]}. (4) Add qnfo-fleet-control/noise-floor.test.mjs, loading the block the way qnfo-fleet-control/improvement.test.mjs does (vm.runInContext over the slice between the markers, exporting ilNoiseFloor). (5) python scripts/worker_release.py bump qnfo-fleet-control --minor --note "..." (a new route and table is a capability), keep deployed-current.worker.js identical, add a probe for /noise-floor to qnfo-fleet-control/probes.json only after python scripts/deploy_probes.py --live qnfo-fleet-control passes against production. Tag each edit with a comment RM-BS-HONEST-MEASURE-1.1.' || char(10) || char(10) ||
 'FORMULA (so nothing is guessed): z = 1.96 + 0.84 = 2.80 (alpha 0.05 two-sided, power 0.8). basis daily (metrics that are one number per day, such as the reader series): sd = sample standard deviation of the n daily values, needs n at least 8 else state insufficient_history; mde_w = 2.80 * sd * sqrt(2 / w) for w in 7, 14, 28 (check: sd 5.0 gives 7.5, 5.3, 3.7); dispersion = sd^2 / mean. basis rolling_lag (metrics whose name ends in _7d, _28d, _30d or _90d, where each daily value is already a mean or rate over that many days, so neighbouring days overlap and the daily sd understates the noise of non-overlapping windows): d = value[t] - value[t - native_window_d] for every pair present, needs at least 4 pairs else insufficient_history; the A/A pair noise is sd(d); sd(d) = sqrt(2) * (noise of one window), so the mde at the native window = 2.80 * sd(d); a longer window of k native windows divides that by sqrt(k), a window shorter than native stays NULL. mde_rel = mde / abs(mean), NULL when the mean is 0. state: ok; insufficient_history; flat_series (sd 0, mde 0, never a divide by zero); unmeasurable_at_this_volume (mde_28d_rel above 1.0, which is a legitimate honest answer, not a failure). Set caveat to the text days are treated as independent, so the floor is optimistic when referrers are shared on every row with basis daily.' || char(10) || char(10) ||
 'DEFINITION OF DONE (merged AND verified live, VERIFY-LIVE-1): after the deploy and one hourly improvement-loop tick, (a) SELECT COUNT(*) AS rows, SUM(state = ok) AS ok_rows FROM metric_noise_floor returns at least 15 rows (14 outcome measures plus ga4_engaged_external_daily) and at least 5 ok; (b) GET https://qnfo-fleet-control.q08.workers.dev/noise-floor answers 200 and contains "ga4_engaged_external_daily"; (c) that row reads mde_7d between 3 and 12 (the first reading was 7.4; it moves as the series grows, so the band is wide on purpose); (d) SELECT COUNT(*) FROM v_output_quality_noise WHERE tol_below_noise = 1 is read and recorded in the issue close_evidence (it names the outcome measures whose fixed tolerance is inside the noise). Write the numbers you read in issue_triage.close_evidence.' || char(10) || char(10) ||
 'DO NOT: change any output_quality_measures row, target, trigger or verdict (that is RM-BS-HONEST-MEASURE-1.2); write to metric_history; count a proxy measure; run an unindexed scan of metric_history or cloud_ops_events (qnfo-audit is 1.5 GB and one query runs at a time); edit a merged migration; add a worker. Failure modes: a floor computed from the series the loops move can be gamed, so only this step writes metric_noise_floor; at 6 readers a day nothing may be detectable and the honest result is unmeasurable_at_this_volume, which redirects effort to B5.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js' || char(10) ||
 'code-anchor: function ilMean(a) {' || char(10) ||
 'code-probe: {"paths":["qnfo-fleet-control/worker.js"],"contains":"RM-BS-HONEST-MEASURE-1.1"}',
 'session:W2-H-3260', 'code', 'medium', 'open', unixepoch() * 1000, unixepoch() * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'ROADMAP-1: QNFO.OPS RM-BS-HONEST-MEASURE-1.1:%' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'ROADMAP-1: QNFO.OPS RM-BS-HONEST-MEASURE-1.2: the improvement loop calls a move inside the noise floor within_noise (shadow first), and the PLUSSING-4 window is sized from the floor',
 'QNFO.OPS; charter pillar autonomy; roadmap row 3260 (RM-BS-HONEST-MEASURE-1), blue-sky bet B4; doer: qnfo-code-orchestrator via the code-task line. Starts only after RM-BS-HONEST-MEASURE-1.1 is merged and verified live (metric_noise_floor and v_metric_window_needed exist: check with SELECT COUNT(*) FROM metric_noise_floor); if it has not landed, take that issue first. Metric it should move: the share of improved or regressed verdicts that are inside the noise floor, read from the shadow events below; success is a claim the fleet withdraws because it was inside the noise (doc B4 Measure).' || char(10) || char(10) ||
 'WHY (read 2026-11-05): qnfo-fleet-control improvementEvaluate(f, nowMs) calls a metric improved when it moved at least 5 percent in its good direction between two 7-day windows (improvement_rate_7d) and metric_regressions_7d counts 15 percent bad moves; neither knows the metric noise. The PLUSSING-4 keep-or-revert check (migrations/2026-11-01-plussing-4.sql, table plus_outcome_checks, workflow row fleet_tasks id management-personas) keeps or reverts a plus after a fixed seven days on its registered outcome measure; for the reader series a 7-day comparison cannot tell a change smaller than +7.4 a day from noise, so most reader-outcome pluses would be kept or reverted on noise.' || char(10) || char(10) ||
 'WORK: (a) In improvementEvaluate, when ops_config il_noise_floor is shadow (default) compute for every evaluable metric whether its move is below mde_7d_rel of its metric_noise_floor row (state ok only; no row or any other state means not judged by the floor) and write ONE cloud_ops_events row per UTC day, kind noise-floor-shadow, status ok, detail JSON {evaluable, improved, regressed, improved_within_noise, regressed_within_noise, metrics_without_floor}; change no verdict. When the key is on, a move below the floor is reported as within_noise and excluded from improvement_rate_7d and metric_regressions_7d. The key ships as shadow; flipping it to on is a later migration after 7 daily shadow events have been read (record the numbers in decision_log with the revert path ops_config il_noise_floor = off). (b) PLUSSING-4 window: new migration migrations/2026-11-<date>-plussing-4-noise-window.sql (BACKUP the row: CREATE TABLE bak_<date>_plus4_noise AS SELECT id, definition, version FROM fleet_tasks WHERE id = management-personas, as migrations/2026-11-01-plussing-4.sql does) that edits the management-personas workflow definition so the seven-day outcome check reads COALESCE((SELECT window_days FROM v_metric_window_needed WHERE metric = <the plus metric>), 7) days and records the window and detectable_at_tol in plus_outcome_checks.evidence; a plus whose measure has detectable_at_tol = 0 is recorded as unmeasurable_at_this_volume and is never kept or reverted on that measure. Read the current definition first (SELECT definition FROM fleet_tasks WHERE id = management-personas) and change only the window expression. (c) tests: extend qnfo-fleet-control/improvement.test.mjs with within-noise cases (a 6 percent move on a floor of 40 percent is within_noise and not improved when the key is on, still improved when shadow); a migration test next to migrations/plussing-3.test.mjs. (d) python scripts/worker_release.py bump qnfo-fleet-control --note "..." and keep deployed-current.worker.js identical. Tag edits RM-BS-HONEST-MEASURE-1.2.' || char(10) || char(10) ||
 'DEFINITION OF DONE (merged AND verified live): SELECT COUNT(*) FROM cloud_ops_events WHERE kind = noise-floor-shadow AND ts > date of the deploy returns at least 1 (use an indexed predicate on kind and ts that the table indexes; check EXPLAIN QUERY PLAN first), and its detail shows improved_within_noise and regressed_within_noise counts; SELECT definition FROM fleet_tasks WHERE id = management-personas contains v_metric_window_needed; record both in issue_triage.close_evidence. The follow-up ROADMAP-1 rows for the remaining B4 items listed in the evidence of roadmap_implementation 3260 are filed by this issue doer when this merges, each with its own code-task and anchor.' || char(10) || char(10) ||
 'DO NOT: flip il_noise_floor to on in the same change; lower or remove any trigger, target or guard metric to make a number look better; count a proxy measure toward a verdict (OUTPUT-QUALITY-LEDGER-1); edit a merged migration. A gain in a target metric while a guard worsens is a regression: if remediation_latest_pass_pct_7d or issue_wontfix_share_7d worsens after the change, revert. Failure mode: the shadow shows nearly every move inside the noise at current volume; that is the finding, and it goes into the close_evidence unedited.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js' || char(10) ||
 'code-anchor: function improvementEvaluate(f, nowMs) {' || char(10) ||
 'code-probe: {"paths":["qnfo-fleet-control/worker.js"],"contains":"RM-BS-HONEST-MEASURE-1.2"}',
 'session:W2-H-3260', 'code', 'medium', 'open', unixepoch() * 1000, unixepoch() * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'ROADMAP-1: QNFO.OPS RM-BS-HONEST-MEASURE-1.2:%' AND status = 'open');

INSERT INTO decision_log
  (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session W2-H (roadmap row 3260)',
       'every other blue-sky bet is judged by B4, so a noise floor and minimum detectable effect for each outcome measure come before any keep or revert that compares two windows',
       'RM-BS-HONEST-MEASURE-1: row 3260 evidence updated with the first reading and the D1 coverage read; slices .1 (metric_noise_floor) and .2 (within_noise shadow, PLUSSING-4 window) filed with code-task lines, anchors, probes and definitions of done',
       'reader_yield_daily 11 days: mean 5.1, sd 5.0, smallest detectable effect of two 7-day windows +7.4 a day; output_quality_measures 14 outcome rows, metric_history points in the last 28 days 29/29/29/29/29/11/11/11/6/6/6/2/0/0; qnfo-fleet-control anchors function ilMean(a) { and function improvementEvaluate(f, nowMs) { each occur once on main',
       'row 3260 stays planned with a doer and two filed slices',
       'one roadmap_implementation row, two agent_issues rows, one decision_log row; no code or table change',
       'the migration Rollback restores the row from bak_20261105_honest_measure_roadmap and closes the two issues',
       'a cold code agent can build the noise floor and the shadow verdict from the issue text alone',
       'after .1 is merged and one improvement-loop tick has run, metric_noise_floor holds at least 15 rows with at least 5 in state ok, and ga4_engaged_external_daily reads mde_7d between 3 and 12',
       'no external reach change',
       'migrations/honest-measure-handoff-1.test.mjs (anchors occur once on main, second run adds nothing)'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE action LIKE 'RM-BS-HONEST-MEASURE-1: row 3260 evidence updated%');
